using FuelUp.Api.Security;
using FuelUp.Domain;
using FuelUp.Infrastructure;
using Microsoft.EntityFrameworkCore;

namespace FuelUp.Api;

/// <summary>
/// Realistic sample data for trying the system, loaded into the FIRST company (the one created at bootstrap).
/// Every order goes through the real business rules (TripService): meter readings, loading, delivery, approval, review —
/// so dashboards, reports and ledgers are consistent. Runs once (marker setting "sample_data"), only when Seed__Sample=true.
/// Driver accounts use the password in Seed__SamplePassword (generated by the host, never in the code).
/// Before real operation start from a clean database: sample orders, meter readings and audit rows cannot be deleted (append-only).
/// </summary>
public static class SampleData
{
    private static readonly TimeSpan Ksa = TimeSpan.FromHours(3);

    public static async Task RunAsync(FuelUpDb db, TenantContext tenant, IConfiguration cfg, ILogger log)
    {
        var company = await db.Companies.IgnoreQueryFilters().OrderBy(c => c.CreatedAt).FirstOrDefaultAsync();
        if (company is null) { log.LogWarning("Sample data skipped: no company yet"); return; }
        tenant.Set(company.Id);
        if (await db.Settings.AnyAsync(s => s.Key == "sample_data"))
        {
            log.LogInformation("Sample data already loaded");
            await SampleCustody.RunAsync(db, log);   // added later: runs once on databases that already have the sample orders
            await SampleFillReports.RunAsync(db, cfg, log);
            return;
        }
        var password = cfg["Seed:SamplePassword"];
        if (Passwords.Problem(password, "driver01") is { } p) { log.LogWarning("Sample data skipped: Seed__SamplePassword refused ({Problem})", p); return; }
        var admin = await db.Users.Where(u => u.Role == Role.Admin).OrderBy(u => u.CreatedAt).FirstAsync();
        log.LogWarning("Loading sample data into company {Company}…", company.Name);

        var rnd = new Random(2026);
        var all = Enum.GetValues<Section>().ToDictionary(s => s, _ => PermissionLevel.Edit);
        var boss = new Actor(admin.Id, null, all, company.Id, Role.Admin);
        var audit = new AuditWriter(db); var ledger = new MeterLedger(db); var assign = new AssignmentService(db, audit);
        var svc = new TripService(db, ledger, assign, audit);
        if (!await db.Settings.AnyAsync(s => s.Key == "tolAbs"))
            db.Settings.AddRange(new Setting { Key = "tolAbs", Value = "20" }, new Setting { Key = "tolPct", Value = "0.3" });

        // ── master data ────────────────────────────────────────────────────────────────────────────────────────────
        var stations = new[]
        {
            new Station { Name = "محطة الظهران (تجريبي)", Type = StationType.Station, City = "الظهران", Lat = 26.2361, Lng = 50.0393 },
            new Station { Name = "حوش ميسان (تجريبي)", Type = StationType.MaysanYard, City = "الدمام", Lat = 26.42, Lng = 50.08 },
            new Station { Name = "أرامكو رأس تنورة (تجريبي)", Type = StationType.Aramco, City = "رأس تنورة", Lat = 26.64, Lng = 50.16 },
        };
        string[] makes = ["مرسيدس-بنز أكتروس", "فولفو FH", "مان TGS", "إيسوزو FVR", "هينو 500", "سكانيا R450", "مرسيدس أكسور", "داف XF"];
        string[] letters = ["ر ط أ", "ب ح د", "س ك ل", "ن ه و", "ع ق ر", "ط م ب", "ح ص ن", "د ل ك"];
        var meters = Enumerable.Range(0, 8).Select(i => new Meter { Serial = $"DEMO-M7-{41000 + i * 37}", Kind = "إلكتروني بطابعة تذاكر" }).ToArray();
        var vehicles = Enumerable.Range(0, 8).Select(i => new Vehicle
        {
            Plate = $"{letters[i]} {3100 + i * 211} (ت)", InternalNo = $"T-{20 + i}", Make = makes[i].Split(' ')[0], Model = string.Join(' ', makes[i].Split(' ').Skip(1)),
            Year = 2017 + i % 7, Capacity = i < 5 ? 32000 : 20000, Compartments = [new(1, i < 5 ? 16000 : 10000), new(2, i < 5 ? 16000 : 10000)], MeterId = meters[i].Id,
        }).ToArray();
        for (var i = 0; i < 8; i++) meters[i].VehicleId = vehicles[i].Id;
        string[] names = ["سالم العتيبي", "خالد الدوسري", "فهد القحطاني", "عبدالله الشمري", "ماجد الحربي", "سعد الغامدي", "تركي المطيري", "ناصر الزهراني", "بندر العنزي", "محمد اليامي"];
        var drivers = names.Select((n, i) => new Driver { Name = n, EmpNo = $"E{200 + i}", Phone = $"05{rnd.Next(10000000, 99999999)}", Type = i < 6 ? DriverType.Aramco : DriverType.SmallTruck }).ToArray();
        var customers = new[]
        {
            new Customer { Name = "مقاولات الجبيل", Project = "مشروع الطريق الدائري", Site = "موقع الكسارة — الجبيل", Recipient = "م. أحمد", Lat = 27.0, Lng = 49.6 },
            new Customer { Name = "مصنع الدمام للحديد", Project = "مولدات المصنع", Site = "المدينة الصناعية الثانية — الدمام", Recipient = "مشرف الصيانة", Lat = 26.37, Lng = 50.15 },
            new Customer { Name = "شركة الخليج للإنشاءات", Project = "أبراج الخبر", Site = "حي العليا — الخبر", Recipient = "م. سامي" },
            new Customer { Name = "مستشفى الأحساء الأهلي", Project = "مولدات الطوارئ", Site = "الهفوف", Recipient = "إدارة المرافق" },
            new Customer { Name = "مزارع القطيف", Project = "مضخات الري", Site = "القطيف — المزارع الشمالية", Recipient = "أبو فيصل" },
            new Customer { Name = "ميناء الملك عبدالعزيز", Project = "معدات الرصيف", Site = "الدمام — الميناء", Recipient = "قسم المعدات" },
        };
        db.AddRange(stations); db.AddRange(meters); db.AddRange(vehicles); db.AddRange(drivers); db.AddRange(customers);
        await db.SaveChangesAsync();

        // ── accounts: 10 drivers + 1 operations supervisor (one bcrypt hash: same test password) ─────────────────────
        var hash = Passwords.Hash(password!);
        var driverUsers = drivers.Select((d, i) => new User
        {
            Username = $"driver{i + 1:00}", DisplayName = d.Name, Role = Role.Driver, DriverId = d.Id, PasswordHash = hash,
        }).ToList();
        foreach (var u in driverUsers) u.Permissions = Permissions.Presets[Role.Driver].Select(kv => new UserPermission { UserId = u.Id, Section = kv.Key, Level = kv.Value }).ToList();
        var sup = new User { Username = "supervisor1", DisplayName = "مشرف التشغيل (تجريبي)", Role = Role.OpsSupervisor, PasswordHash = hash };
        sup.Permissions = Permissions.Presets[Role.OpsSupervisor].Select(kv => new UserPermission { UserId = sup.Id, Section = kv.Key, Level = kv.Value }).ToList();
        db.Users.AddRange(driverUsers); db.Users.Add(sup);
        await db.SaveChangesAsync();

        // ── assignments and approved meter baselines ────────────────────────────────────────────────────────────────
        for (var i = 0; i < 8; i++) await assign.AssignVehicleAsync(boss, vehicles[i].Id, drivers[i].Id, "توزيع تجريبي");
        for (var i = 0; i < customers.Length; i++) await assign.AssignCustomerAsync(boss, customers[i].Id, drivers[i % 8].Id);
        await db.SaveChangesAsync();
        var last = new Dictionary<Guid, decimal>(); var odo = new Dictionary<Guid, decimal>();
        for (var i = 0; i < 8; i++)
        {
            var b = 40000m + rnd.Next(0, 1400) * 100;
            await ledger.SetBaselineAsync(boss, meters[i].Id, b);
            last[meters[i].Id] = b; odo[vehicles[i].Id] = 80000 + rnd.Next(0, 300000);
        }
        await db.SaveChangesAsync();

        // ── ~80 orders over the last 45 days, in chronological order, through the real workflow ────────────────────
        var todayKsa = DateTime.UtcNow.Add(Ksa).Date;
        var plans = new List<(DateTime At, string Target)>();
        for (var d = 44; d >= 1; d--)
        {
            var day = todayKsa.AddDays(-d);
            if (day.DayOfWeek == DayOfWeek.Friday) continue;
            var n = day.DayOfWeek == DayOfWeek.Saturday ? 1 : rnd.Next(1, 4);
            for (var k = 0; k < n; k++) plans.Add((day.AddHours(6 + rnd.Next(0, 8)).AddMinutes(rnd.Next(0, 60)), "Approved"));
        }
        // the most recent days hold the work in progress
        var recent = plans.Where(x => x.At > todayKsa.AddDays(-3)).Select(x => plans.IndexOf(x)).ToList();
        foreach (var i in recent.Take(3)) plans[i] = (plans[i].At, "AwaitingApproval");
        var older = Enumerable.Range(0, plans.Count).Where(i => plans[i].At < todayKsa.AddDays(-3)).OrderBy(_ => rnd.Next()).ToList();
        foreach (var i in older.Take(5)) plans[i] = (plans[i].At, "UnderReview");
        foreach (var i in older.Skip(5).Take(3)) plans[i] = (plans[i].At, "Resolved");
        foreach (var i in older.Skip(8).Take(2)) plans[i] = (plans[i].At, "Cancelled");
        var nowKsa = DateTime.UtcNow.Add(Ksa);
        var startToday = nowKsa.Hour >= 8 ? nowKsa.AddHours(-2) : todayKsa.AddHours(6);
        plans.Add((startToday, "EnRoute")); plans.Add((startToday.AddMinutes(25), "EnRoute")); plans.Add((startToday.AddMinutes(50), "Loaded"));
        for (var k = 0; k < 4; k++) plans.Add((startToday.AddMinutes(60 + k * 10), "WaitingLoad"));
        plans = plans.OrderBy(x => x.At).ToList();

        decimal[] sizes = [3000, 4000, 5000, 6000, 8000, 10000, 12000, 15000];
        var seq = 0;
        foreach (var (atKsa, target) in plans)
        {
            seq++;
            var vi = rnd.Next(0, 8); var driver = drivers[vi]; var vehicle = vehicles[vi]; var meter = meters[vi];
            var cust = customers[rnd.Next(customers.Length)]; var st = stations[rnd.Next(10) < 5 ? 2 : rnd.Next(10) < 6 ? 0 : 1];
            var qty = sizes[rnd.Next(vehicle.Capacity >= 32000 ? sizes.Length : 6)];
            var at = new DateTimeOffset(atKsa - Ksa, TimeSpan.Zero);
            var t = await svc.CreateAsync(boss, new CreateTrip(cust.Id, driver.Id, vehicle.Id, st.Id, $"{(st.Type == StationType.Aramco ? "AR" : st.Type == StationType.MaysanYard ? "MY" : "ST")}-{7700 + seq}", "ديزل", qty, null, 0.85m));
            if (target == "Cancelled") { await svc.CancelAsync(boss, t.Id, "ألغى العميل الطلب"); await Backdate(db, t.Id, at, 0); continue; }
            if (target == "WaitingLoad") { await Backdate(db, t.Id, at, 0); continue; }

            var drv = boss with { DriverId = driver.Id };
            var start = last[meter.Id]; var loaded = qty; var end = start + loaded + rnd.Next(-3, 4);
            odo[vehicle.Id] += rnd.Next(40, 260);
            await svc.LoadAsync(drv, t.Id, new LoadInput(vehicle.Id, qty, $"DOC-{50000 + seq}", odo[vehicle.Id], null, start, end, $"S{rnd.Next(1000, 9999)}-{rnd.Next(1000, 9999)}", st.Name, st.Lat, st.Lng, at.AddMinutes(35)));
            last[meter.Id] = end;
            if (target == "Loaded") { await Backdate(db, t.Id, at, 1); continue; }
            await svc.DepartAsync(drv, t.Id);
            if (target == "EnRoute") { await Backdate(db, t.Id, at, 2); continue; }
            await svc.ArriveAsync(drv, t.Id, new ArriveInput(cust.Site, cust.Lat, cust.Lng));
            await svc.UnloadAsync(drv, t.Id, new UnloadInput(true, null));
            var delivered = end - start;
            var shortfall = target is "UnderReview" or "Resolved" ? rnd.Next(150, 420) : rnd.Next(0, 9);
            var after = end + delivered;
            await svc.DeliverAsync(drv, t.Id, new DeliverInput(end, after, $"TK-{80000 + seq}", delivered - shortfall, 0, 0, $"RC-{30000 + seq}", false, at.AddHours(3)));
            last[meter.Id] = after;
            if (target == "Approved") await svc.ApproveAsync(boss, t.Id, "مطابق للسند");
            if (target == "Resolved") await svc.ResolveAsync(boss, t.Id, "تم التحقق: فاقد تبخر وتسريب بسيط في الخرطوم، يُحمّل على المورد");
            await Backdate(db, t.Id, at, 3);
        }

        // ── attendance: last 14 days, Sunday–Thursday, for drivers, supervisor and the admin ────────────────────────
        var people = driverUsers.Select(u => u.Id).Append(sup.Id).Append(admin.Id).ToList();
        var forgotten = driverUsers[8].Id;   // one forgotten check-out three days ago, to show the warning
        foreach (var uid in people)
        {
            for (var d = 14; d >= 0; d--)
            {
                var day = todayKsa.AddDays(-d);
                if (day.DayOfWeek is DayOfWeek.Friday or DayOfWeek.Saturday) continue;
                if (rnd.Next(10) == 0) continue;   // ~10 % absent
                var inK = day.AddHours(6).AddMinutes(30 + rnd.Next(0, 70));
                var outK = day.AddHours(14).AddMinutes(20 + rnd.Next(0, 110));
                var isToday = d == 0;
                if (isToday && inK > nowKsa) continue;
                var openToday = isToday && (outK > nowKsa || rnd.Next(2) == 0) && uid != forgotten;
                if (uid == forgotten && d < 3) continue;
                var rec = new AttendanceRecord
                {
                    UserId = uid, Day = DateOnly.FromDateTime(day), CheckInAt = new DateTimeOffset(inK - Ksa, TimeSpan.Zero),
                    CheckOutAt = openToday || (uid == forgotten && d == 3) ? null : new DateTimeOffset(outK - Ksa, TimeSpan.Zero), Note = "تجريبي",
                };
                db.Attendance.Add(rec);
            }
        }
        db.Settings.Add(new Setting { Key = "sample_data", Value = DateTimeOffset.UtcNow.ToString("o") });
        await db.SaveChangesAsync();
        await SampleCustody.RunAsync(db, log);
        await SampleFillReports.RunAsync(db, cfg, log);
        log.LogWarning("Sample data loaded: {Trips} orders, {Drivers} drivers, {Vehicles} vehicles. Driver accounts driver01–driver10 and supervisor1 use Seed__SamplePassword.", plans.Count, drivers.Length, vehicles.Length);
    }

    /// <summary>Moves an order's timestamps to its planned time (the workflow ran "now"); meter readings and audit rows stay append-only.</summary>
    internal static async Task Backdate(FuelUpDb db, Guid id, DateTimeOffset at, int stage)
    {
        var t = await db.Trips.Include(x => x.Loading).Include(x => x.Deliveries).FirstAsync(x => x.Id == id);
        t.CreatedAt = at.AddMinutes(-90);
        if (t.Loading != null) t.Loading.At = at.AddMinutes(35);
        if (stage >= 2 && t.DepartedAt != null) t.DepartedAt = at.AddMinutes(55);
        foreach (var d in t.Deliveries)
        {
            d.ArrivedAt = at.AddHours(2);
            if (d.UnloadStartAt != null) d.UnloadStartAt = at.AddHours(2).AddMinutes(10);
            if (d.SubmittedAt != null) d.SubmittedAt = at.AddHours(2).AddMinutes(40);
        }
        if (t.ApprovedAt != null) t.ApprovedAt = at.AddHours(5);
        if (t.ClosedAt != null) t.ClosedAt = at.AddHours(5);
        await db.SaveChangesAsync();
    }
}
